  function d6RouteExplorer(){const pts=[[43,23],[51,46],[25,65],[11,87],[58,49],[42,59],[82,82],[67,90]];return `<section class="route-explorer"><div class="day2-city-map route-map d6-route-map" role="img" aria-label="Ocho puntos del Día 06 en Gotemburgo">${d6CitySvg()}${pts.map((p,i)=>`<button type="button" class="route-pin ${state.exploredPlaces.includes(i)?"seen":""}" style="--x:${p[0]}%;--y:${p[1]}%" data-place="${i}" aria-label="Abrir ${esc(DATA.routePlaces[i][0])}">${state.exploredPlaces.includes(i)?"✓":i+1}</button>`).join("")}</div>${cityKey()}<p class="map-credit">Plano propio basado en © OpenStreetMap contributors · orientación, no navegación</p><p class="placement-progress">Lugares abiertos: <strong>${state.exploredPlaces.length} de 8</strong></p><div id="place-detail"></div></section>`}
