  function d6Coast1621Svg(){return `<svg class="schematic-map regional d6-coast" viewBox="0 0 420 330" role="img" aria-label="Costa occidental sueca y fronteras de 1621"><rect width="420" height="330" fill="#b9dce8"/><path fill="#e8d2c2" stroke="#456779" d="M0 0h178l18 73-45 73-43 28H0z"/><path fill="#e8d2c2" stroke="#456779" d="M0 249l96-22 53-31 45 46-8 88H0z"/><path fill="#f4e7a9" stroke="#456779" d="M178 0h242v330H186l8-88-45-46-41 24v-46l43-28 45-73z"/><path fill="#75b8d0" stroke="#1f6f8e" d="M303 24c48 15 68 47 42 75-35 24-92 10-97-26 1-27 23-45 55-49z"/><path class="d6-route" d="M305 66Q267 107 241 148Q202 186 151 199"/><circle class="schem-point" cx="305" cy="66" r="6"/><circle class="schem-point" cx="241" cy="148" r="6"/><circle class="schem-point" cx="151" cy="199" r="7"/><text class="schem-label" x="313" y="57">Vänern</text><text class="schem-label" x="250" y="141">Trollhättan</text><text class="schem-label" x="159" y="218">Gotemburgo</text><text class="schem-water-label" x="30" y="211">KATTEGAT</text><text class="schem-water-label" x="193" y="174">GÖTA ÄLV</text><text class="schem-country" x="22" y="78">BOHUSLÄN</text><text class="schem-country" x="14" y="101">NORUEGA–DINAMARCA</text><text class="schem-country" x="116" y="187">CORREDOR</text><text class="schem-country" x="116" y="207">SUECO</text><text class="schem-country" x="45" y="282">HALLAND</text><text class="schem-country" x="39" y="303">DINAMARCA</text><text class="schem-country" x="304" y="215">SUECIA</text></svg>`}
