  function d6TeaWorld(){
    const bounds=[-28,150,-43,66],m=baseMap(bounds,"Ruta marítima aproximada de Gotemburgo a Cantón por el cabo de Buena Esperanza");let s=m.svg;
    const land=pts=>{const d=pts.map((p,i)=>{const q=project(p[0],p[1],bounds,m.W,m.H);return`${i?"L":"M"}${q[0]},${q[1]}`}).join(" ");s+=`<path class="country d6-world-land" d="${d}Z"/>`};
    land([[-17,37],[2,37],[12,33],[25,32],[34,27],[43,12],[51,11],[49,3],[43,-9],[36,-18],[29,-29],[18,-35],[11,-29],[5,-17],[-5,0],[-16,15],[-17,37]]);
    land([[26,40],[39,51],[61,64],[95,66],[130,57],[150,49],[145,40],[132,35],[126,40],[121,24],[113,20],[109,9],[104,1],[99,6],[94,18],[87,22],[77,7],[68,23],[55,25],[45,34],[26,40]]);
    land([[112,-11],[130,-10],[144,-15],[153,-28],[146,-39],[124,-38],[113,-28],[112,-11]]);
    land([[95,5],[101,1],[106,-6],[103,-10],[98,-5],[95,5]]);land([[105,-6],[115,-7],[115,-9],[106,-9],[105,-6]]);land([[47,-13],[50,-16],[49,-25],[46,-20],[47,-13]]);
    const lines=[[11.97,57.71,-8,30,"Atlántico norte"],[-8,30,3,2,"Atlántico"],[3,2,18.47,-34.36,"costa africana"],[18.47,-34.36,62,-27,"Índico"],[62,-27,105.7,-6,"monzones"],[105.7,-6,110,8,"mar de China"],[110,8,113.26,23.13,"Perlas"]];
    lines.forEach(l=>{const a=project(l[0],l[1],bounds,m.W,m.H),b=project(l[2],l[3],bounds,m.W,m.H);s+=`<path class="route-line dashed" d="M${a[0]},${a[1]} Q${(a[0]+b[0])/2},${Math.min(a[1],b[1])-12} ${b[0]},${b[1]}"/><text class="route-distance" x="${(a[0]+b[0])/2}" y="${(a[1]+b[1])/2-8}">${l[4]}</text>`});
    [["GOTEMBURGO",11.97,57.71,-77,-8],["CABO DE BUENA ESPERANZA",18.47,-34.36,8,18],["ESTRECHO DE SONDA",105.7,-6,-94,19],["CANTÓN",113.26,23.13,8,-8]].forEach(x=>{const p=project(x[1],x[2],bounds,m.W,m.H);s+=`<circle class="map-marker" cx="${p[0]}" cy="${p[1]}" r="5"/><line class="map-label-line" x1="${p[0]}" y1="${p[1]}" x2="${p[0]+x[3]*.72}" y2="${p[1]+x[4]*.72}"/><text class="map-label" x="${p[0]+x[3]}" y="${p[1]+x[4]}">${x[0]}</text>`});
    [["ÁFRICA",14,11],["ASIA",78,46]].forEach(x=>{const p=project(x[1],x[2],bounds,m.W,m.H);s+=`<text class="schem-water-label d6-world-name" x="${p[0]}" y="${p[1]}">${x[0]}</text>`});
    return `<div class="geo-map d6-world-map">${s}</svg></div>`
  }
