    d6Coat:`<figure class="d6-photo-card coat"><img src="${imgBase}goteborg-vapen.svg" alt="Escudo oficial de Gotemburgo con león, espada y tres coronas"><figcaption><strong>Escudo oficial de Gotemburgo.</strong><br><span class="d6-heraldic-direction">← diestra heráldica · el león mira hacia la siniestra heráldica →</span></figcaption></figure>`,
    d6OldCities:`<div class="d6-process"><span>1473<br><b>NYA LÖDÖSE</b></span><i>habitantes · oficios · redes →</i><span>1621<br><b>GOTEMBURGO</b></span></div>`,
    d6Move:`<div class="evidence-grid three"><div><b>REDES</b><span>clientes</span></div><div><b>OFICIOS</b><span>experiencia</span></div><div><b>MEMORIA</b><span>comunidad</span></div></div>`,
    d6Council:`<div class="d6-council"><span>4<br><b>suecos</b></span><span>3<br><b>neerlandeses</b></span><span>3<br><b>alemanes</b></span><span>2<br><b>escoceses</b></span></div>`,
    d6Clay:`<div class="d6-photo-pair"><figure><img src="${imgBase}amsterdam-canals-cc0.jpg" alt="Casas junto a un canal de Ámsterdam"><figcaption><b>Ámsterdam</b><br>1613 · ampliación del anillo de canales</figcaption></figure><figure><img src="${imgBase}goteborg-vallgraven-cc-by-sa.jpg" alt="Canal Vallgraven de Gotemburgo"><figcaption><b>Gotemburgo</b><br>1621 · nueva ciudad junto al Göta älv</figcaption></figure></div><div class="d6-city-pair"><div><b>ÁMSTERDAM</b><strong>1275</strong><span>primera referencia escrita</span><em>1613 · gran ampliación de canales</em></div><i>experiencia neerlandesa<br>↓</i><div><b>GOTEMBURGO</b><strong>1621</strong><span>fundación de la ciudad</span><em>canales, pilotes, foso y muelles</em></div></div><svg class="schematic-map d6-northsea" viewBox="0 0 420 190" role="img" aria-label="Situación de Ámsterdam y Gotemburgo alrededor del mar del Norte"><rect width="420" height="190" fill="#b9dce8"/><path fill="#eee6d2" stroke="#58717c" d="M0 0h154l-18 55-35 46-14 89H0zM222 0h198v190H265l-18-54-42-29 29-48z"/><text class="schem-water-label" x="126" y="102">MAR DEL NORTE</text><circle class="schem-point" cx="118" cy="145" r="6"/><text class="schem-label" x="62" y="169">ÁMSTERDAM</text><circle class="schem-point" cx="256" cy="55" r="6"/><text class="schem-label" x="268" y="49">GOTEMBURGO</text><path class="d6-route" d="M124 139Q182 75 250 58"/></svg><div class="d6-section"><span class="house">CASA</span><i class="pile p1"></i><i class="pile p2"></i><i class="pile p3"></i><b>ARCILLA HÚMEDA</b><span class="channel">CANAL · DRENAJE</span></div>`,
