  const DATA=window.DAY6_DATA||window.DAY5_DATA||window.DAY4_DATA||window.DAY3_DATA||window.DAY2_DATA, isDay6=!!window.DAY6_DATA, isDay5=!!window.DAY5_DATA, isDay4=!!window.DAY4_DATA, isDay3=!!window.DAY3_DATA, META=DATA.meta||{};
  const STORE=META.store||"codigo-gripsholm-day02-v1", missions=DATA.missions, DAY=META.day||"02";
