  function logo(){return `<div class="code-logo"><p class="kicker">TRANSMISIÓN NO IDENTIFICADA</p><h1>CÓDIG<span class="logo-o">O<span class="logo-crowns">♛♛♛</span></span><br>GRIPSHOLM</h1><p class="tagline">ONCE CLAVES · DIEZ DÍAS · UN MAPA BORRADO</p></div>`}
  function render(){window.scrollTo(0,0);const views={landing,intro,activation,missionCover,key,missionEnd,correctionIntro,correction,verified,fundFinal,ending:isDay6?ending6:isDay5?ending5:isDay4?ending4:ending,result:isDay6?result6:isDay5?result5:isDay4?result4:result};(views[state.stage]||landing)()}
  function dayResumeStage(){if(state.completedMissions.length>=8)return state.failedKeys.length&&!state.correctionSkipped?"correctionIntro":"verified";return state.completedMissions.length?"missionCover":"intro"}

  function landing(){setChrome({show:false,dark:true});screen.className="screen dark center";screen.innerHTML=`${logo()}<div class="signal"><i></i><i></i><i></i><i></i></div><p class="kicker">DÍA ${DAY} · ${META.place||"ESTOCOLMO"}</p><h2>${META.landing||"Un nombre ha sido sustituido por una acusación."}</h2><div class="mission-stats"><div><strong>30</strong><small>claves</small></div><div><strong>8</strong><small>misiones</small></div><div><strong>🪙 300+</strong><small>kr mínimo diario</small></div></div><p class="muted">${state.completedMissions.length?"Tu progreso sigue guardado en este dispositivo.":META.openingTime||"Primera apertura recomendada: 20–25 minutos. Puedes continuar durante el día."}</p>`;setActions([{label:state.completedMissions.length?"Retomar la transmisión":"Abrir la transmisión",run:()=>{if(!state.openedAt)state.openedAt=new Date().toISOString();state.stage=dayResumeStage();save();render()}}],true)}
