  function cityKey(){return `<div class="city-map-key">${DATA.routePlaces.map((p,i)=>`<span><b>${i+1}</b>${esc(p[0])}</span>`).join("")}</div>`}
  function routeMapMarkup(){if(isDay6)return d6RouteExplorer();if(isDay5)return d5RouteExplorer();if(isDay4)return d4RouteExplorer();if(isDay3)return d3RouteExplorer();const pts=cityStops();return `<section class="route-explorer"><div class="day2-city-map route-map" role="img" aria-label="Mapa esquemático de Estocolmo, Djurgården y los ocho puntos del día">${cityMapBase()}${pts.map((p,i)=>`<button type="button" class="route-pin ${state.exploredPlaces.includes(i)?"seen":""}" style="--x:${p[0]}%;--y:${p[1]}%" data-place="${i}" aria-label="Abrir ${esc(DATA.routePlaces[i][0])}">${state.exploredPlaces.includes(i)?"✓":i+1}</button>`).join("")}</div>${cityKey()}<p class="map-credit">Mapa esquemático de orientación · no sustituye un navegador</p><p class="placement-progress">Lugares abiertos: <strong>${state.exploredPlaces.length} de 8</strong></p><div id="place-detail"></div></section>`}
  function bindRouteMap(){const routeCount=META.routeCount||8;screen.querySelectorAll("[data-place]").forEach(b=>b.onclick=()=>{const i=+b.dataset.place;if(!state.exploredPlaces.includes(i)){state.exploredPlaces.push(i);if(state.exploredPlaces.length===routeCount&&!state.awarded.route){state.balance+=5;state.bonus+=5;state.awarded.route=5}save()}const [name,copy]=DATA.routePlaces[i];$("#place-detail").innerHTML=`<article class="route-detail"><span class="route-number">${i+1}</span><div><strong>${esc(name)}</strong><p>${copy}</p>${isDay6&&i===5?`<p><strong>No era una iglesia:</strong> sus arcos y cubierta dieron nombre a un mercado de pescado.</p>`:""}${state.exploredPlaces.length===routeCount?`<p class="reward">ORIENTACIÓN COMPLETA · +5 kr</p>`:""}</div></article>`;b.classList.add("seen");if(isDay6||isDay5)b.innerHTML=`<b>✓</b><span>${esc(name)}</span>`;else b.textContent="✓";screen.querySelector(".placement-progress").innerHTML=`Lugares abiertos: <strong>${state.exploredPlaces.length} de ${routeCount}</strong>`;if(state.exploredPlaces.length===routeCount){const next=actions.querySelector('[data-action="0"]');if(next)next.disabled=false}updateFund()})}
  function activation(){setChrome({show:false,dark:true});screen.className="screen dark center";screen.innerHTML=`${logo()}<p class="kicker">DÍA ${DAY} ACTIVADO</p><h2>${META.title||"Veinte minutos a flote"}</h2><div class="coordinate">MISIONES · 0/8<br>CLAVES · 0/30<br>FONDO · ${state.balance} kr<br>OBJETIVO · ${META.objective||"RETIRAR SABOTAJE"}</div><p>${META.objectiveCopy||"Recuperarás cuatro comprobaciones: propósito, advertencia, ruta y regreso."}</p>`;setActions([{label:"Comenzar la misión 1",run:()=>{state.stage="missionCover";save();render()}}],true)}
  function fundMessage(){const missing=Math.max(0,300-state.balance);if(state.spent)return `${state.balance-state.spent} kr permanecen en reserva.`;if(!missing)return "La transmisión ya está asegurada. Continúa para completar la ruta y aumentar la reserva.";return `Has recuperado ${state.balance} kr. Faltan ${missing} kr para asegurar el canal.`}
  function riskMarkup(){const levels=["BAJO","BAJO","MEDIO","MEDIO","MEDIO","ALTO","ALTO","CRÍTICO"],level=levels[state.mission];return `<div class="risk-indicator risk-${level.toLowerCase()}"><span>RIESGO DE PÉRDIDA DE LA RUTA</span><strong>${level}</strong><i><b style="--risk:${state.mission+1}"></b></i></div>`}
  function missionCover(){const m=missions[state.mission];setChrome({progress:state.completedMissions.length/8*100});screen.className="screen";screen.innerHTML=`<p class="kicker">DÍA ${DAY} · MISIÓN ${state.mission+1} DE 8</p>${riskMarkup()}<div class="speaker-chip">${m.speaker} · canal escrito</div><article class="mission-cover"><span class="mission-index">${String(state.mission+1).padStart(2,"0")}</span><p class="obstacle"><strong>${m.speaker}:</strong> ${m.obstacle}</p><h2>${m.title}</h2><p>${m.goal}</p><div class="mission-stats"><div><strong>${m.keys}</strong><small>claves</small></div><div><strong>${m.time}</strong><small>duración</small></div><div><strong>${m.minimum}</strong><small>kr mínimo</small></div></div><div class="fund-status">${fundMessage()}<br><strong>Completar la misión libera ${m.minimum} kr mínimo.</strong></div></article>`;setActions([{label:m.action,run:()=>{state.key=0;state.stage="key";save();render()}}])}
