  function key(){const m=missions[state.mission],q=m.questions[state.key],scope=scopeFor(q);setChrome({progress:(state.mission+state.key/m.keys)/8*100});screen.className="screen";screen.innerHTML=`<p class="key-count">MISIÓN ${state.mission+1} DE 8 · CLAVE ${state.key+1} DE ${m.keys}</p>${riskMarkup()}${narrative(q)}<h2>${q.title}</h2><p>${q.prompt}</p>${onsiteMarkup(q,scope)}${visual(q.visual,q,scope)}${storyInterlude(q)}${questionMarkup(q,scope)}<div id="feedback"></div>`;bindOnsite(q,scope);bindQuestion(q,scope,false)}
  function onsiteMarkup(q,scope){if(!q.onsite)return"";const p=prog(scope);return `<div class="onsite-choice"><button type="button" class="secondary" data-onsite="found">Lo he encontrado</button><button type="button" class="secondary" data-onsite="visual">No estoy allí · ver ejemplo</button>${p.onsite?`<p class="onsite-status">✓ ${p.onsite==="found"?"Hallazgo confirmado":"Ejemplo visual abierto"}</p>`:""}</div>`}
