  function optionMarkup(q,scope){const p=prog(scope),fixed=p.fixed||[],selected=p.selected||[],choices=shuffleFor(q.options.map((label,index)=>({label,index})),scope,"optionOrder",x=>x.index);return `<div class="options">${choices.map(x=>`<button type="button" class="option ${fixed.includes(x.index)?"locked":selected.includes(x.index)?"selected":""}" data-option="${x.index}" ${fixed.includes(x.index)?"disabled":""}>${esc(x.label)}${fixed.includes(x.index)?" · ✓":""}</button>`).join("")}</div>${q.dossier?`<details class="dossier"><summary>AMPLIAR EL CONTEXTO</summary><p>${q.dossier}</p></details>`:""}`}
  function matchMarkup(q,scope,solution=false){const p=prog(scope);p.fixed||={};p.pending||={};const left=solution?q.pairs:shuffleFor(q.pairs,scope,"matchLeft",x=>x[0]),right=solution?q.pairs:shuffleFor(q.pairs,scope,"matchRight",x=>x[1]),used=[...Object.values(p.fixed),...Object.values(p.pending)];return `<div class="match-columns"><div>${left.filter(x=>solution||!used.includes(x[0])).map(x=>`<button class="option ${p.source===x[0]?"selected":""}" data-source="${esc(x[0])}" ${solution?"disabled":""}>${esc(x[0])}</button>`).join("")}</div><div>${right.map(x=>`<button class="option ${solution||p.fixed[x[1]]?"locked":p.pending[x[1]]?"selected":""}" data-target="${esc(x[1])}" ${solution||p.fixed[x[1]]?"disabled":""}>${esc(x[1])}${solution||p.fixed[x[1]]?" · ✓":""}</button>`).join("")}</div></div>${solution?"":`<p class="placement-progress">Relaciones fijadas: ${Object.keys(p.fixed).length} de ${q.pairs.length}</p>`}`}
