  function exploreMarkup(q,scope){const p=prog(scope);p.opened||=[];return `<div class="explore-grid">${q.items.map((x,i)=>`<button class="explore-item ${p.opened.includes(i)?"opened":""}" data-explore="${i}"><span>${p.opened.includes(i)?"✓":String(i+1).padStart(2,"0")}</span><strong>${esc(x[0])}</strong><small>${p.opened.includes(i)?esc(x[1]):"Toca para abrir"}</small></button>`).join("")}</div><p class="placement-progress">Señales abiertas: ${p.opened.length} de ${q.items.length}</p>`}
  function bindQuestion(q,scope,correction){const p=prog(scope);if(p.complete){success(q,scope,correction);return}if(q.type==="single"||q.type==="speech")return bindSingle(q,scope,correction);if(q.type==="decision")return bindDecision(q,scope,correction);if(q.type==="multi")return bindMulti(q,scope,correction);if(q.type==="match")return bindMatch(q,scope,correction);if(q.type==="order")return bindOrder(q,scope,correction);if(q.type==="explore")return bindExplore(q,scope,correction)}
  function markAttempt(q,scope,correct,correction){const p=prog(scope);p.attempts=(p.attempts||0)+1;if(!correct&&!correction&&!state.failedKeys.includes(q.id))state.failedKeys.push(q.id);save()}
  function complete(q,scope,correction){const p=prog(scope);if(p.complete)return;p.complete=true;if(correction){if(!state.correctedKeys.includes(q.id))state.correctedKeys.push(q.id)}else{if(!state.completedKeys.includes(q.id))state.completedKeys.push(q.id);if((p.attempts||0)===1&&!state.awarded[`bonus-${q.id}`]&&q.type!=="explore"){state.balance+=5;state.bonus+=5;state.awarded[`bonus-${q.id}`]=5}}save();renderCurrent(q,correction)}
