  function bindMulti(q,scope,correction){const p=prog(scope);p.fixed||=[];p.selected||=[];screen.querySelectorAll("[data-option]").forEach(b=>b.onclick=()=>{const i=+b.dataset.option;p.selected=p.selected.includes(i)?p.selected.filter(x=>x!==i):[...p.selected,i];save();renderCurrent(q,correction)});setActions([{label:"Comprobar la selección",disabled:!p.selected.length,run:()=>{const good=p.selected.filter(i=>q.answer.includes(i)),bad=p.selected.filter(i=>!q.answer.includes(i));p.fixed=[...new Set([...p.fixed,...good])];p.selected=[];const ok=p.fixed.length===q.answer.length&&!bad.length;markAttempt(q,scope,ok,correction);if(ok)complete(q,scope,correction);else{save();renderCurrent(q,correction,`${good.length?`Has fijado ${p.fixed.length} de ${q.answer.length}. `:""}${q.hint}`)}}}])}
  function bindMatch(q,scope,correction){const p=prog(scope);p.fixed||={};p.pending||={};screen.querySelectorAll("[data-source]").forEach(b=>b.onclick=()=>{p.source=b.dataset.source;save();renderCurrent(q,correction)});screen.querySelectorAll("[data-target]").forEach(b=>b.onclick=()=>{const t=b.dataset.target;if(!p.source||p.fixed[t])return;Object.keys(p.pending).forEach(k=>{if(p.pending[k]===p.source)delete p.pending[k]});p.pending[t]=p.source;p.source=null;save();renderCurrent(q,correction)});const ready=Object.keys(p.fixed).length+Object.keys(p.pending).length===q.pairs.length;setActions([{label:"Comprobar relaciones",disabled:!ready,run:()=>{q.pairs.forEach(x=>{if(p.pending[x[1]]===x[0]){p.fixed[x[1]]=x[0];delete p.pending[x[1]]}else delete p.pending[x[1]]});const ok=Object.keys(p.fixed).length===q.pairs.length;markAttempt(q,scope,ok,correction);if(ok)complete(q,scope,correction);else{save();renderCurrent(q,correction,`Has fijado ${Object.keys(p.fixed).length} de ${q.pairs.length}. ${q.hint}`)}}}])}
  function bindOrder(q,scope,correction){const p=prog(scope);screen.querySelectorAll("[data-move]").forEach(b=>b.onclick=()=>{const [i,d]=b.dataset.move.split(",").map(Number),j=i+d;if(j<0||j>=p.order.length)return;[p.order[i],p.order[j]]=[p.order[j],p.order[i]];save();renderCurrent(q,correction)});setActions([{label:"Comprobar la secuencia",run:()=>{const ok=p.order.every((x,i)=>x===q.answer[i]);markAttempt(q,scope,ok,correction);if(ok)complete(q,scope,correction);else{save();renderCurrent(q,correction,q.hint)}}}])}
  function bindExplore(q,scope,correction){const p=prog(scope);p.opened||=[];screen.querySelectorAll("[data-explore]").forEach(b=>b.onclick=()=>{const i=+b.dataset.explore;if(!p.opened.includes(i))p.opened.push(i);save();renderCurrent(q,correction)});setActions([{label:p.opened.length===q.items.length?"Sellar la clave":"Abre todas las señales",disabled:p.opened.length!==q.items.length,run:()=>{markAttempt(q,scope,true,correction);complete(q,scope,correction)}}])}
  function renderCurrent(q,correction,failure){correction?correctionQuestion(q):key();if(failure){$("#feedback").innerHTML=`<div class="feedback bad"><strong>La clave sigue dañada</strong><p>${failure}</p></div>`}}
  function success(q,scope,correction){const speech=q.type==="speech"?speechMarkup(q):"";$("#feedback").innerHTML=`<div class="feedback"><strong>${q.success||"CLAVE RECUPERADA"}</strong><p>${q.explanation}</p>${!correction&&state.awarded[`bonus-${q.id}`]?`<p class="reward">+5 kr por resolver al primer intento</p>`:""}</div>${speech}${solutionExtra(q,scope)}`;if(q.type==="speech")bindSpeech(q);setActions([{label:correction?(state.correctedKeys.length===state.failedKeys.length?"Sellar la ruta":"Volver a la corrección"):nextLabel(),run:()=>advance(correction)}])}
  function nextLabel(){const m=missions[state.mission];return state.key===m.keys-1?"Completar la misión":"Ir a la siguiente clave"}
  function solutionExtra(q,scope){let h="";if(q.type==="match")h+=`<div class="puzzle-card"><p class="kicker">REGISTRO COMPLETO</p>${q.pairs.map(x=>`<p><strong>${esc(x[0])}</strong><br>${esc(x[1])}</p>`).join("")}</div>`;if(q.type==="order")h+=`<div class="puzzle-card"><p class="kicker">SECUENCIA RECUPERADA</p>${orderMarkup(q,scope,true)}</div>`;if(q.visual)h+=`<div class="puzzle-card solution-visual"><p class="kicker">EVIDENCIA RECUPERADA</p>${visual(q.visual,q,scope,true)}</div>`;if(q.finalSignal)h+=isDay6?`<div class="coordinate">GÖTA ÄLV · PUERTA OCCIDENTAL<br>1621 · PLANO<br>1731 · TÉ<br>2026 · CONTENEDOR → COSTA NORTE</div>`:isDay5?`<div class="coordinate">FINLANDIA · 1809<br>KARLSBORG · 1819<br>S/S TRAFIK · 1892<br>RUTA MODERNA · HÖKERUM → REGIÓN TEXTIL</div>`:isDay4?`<div class="coordinate">GRIETA · ESTRUCTURA ANTIGUA<br>HIELO · TRANSPORTE Y DESHIELO<br>FUEGO · MEMORIA DEL BOSQUE<br>LEYENDA · RELATO BIEN ETIQUETADO</div>`:isDay3?`<div class="coordinate">PUENTE · PASO Y NOMBRE<br>HIERRO · BERGSLAGEN<br>CASTILLO · CONTROL DEL CRUCE<br>BOSQUE · TIVEDEN</div>`:`<div class="coordinate">PROPÓSITO · GUERRA Y PODER<br>ADVERTENCIA · INESTABILIDAD CONOCIDA<br>RUTA · VAXHOLM → ÄLVSNABBEN<br>REGRESO · 1956 → 1961</div>`;return h}
  function advance(correction){if(correction)state.stage=state.correctedKeys.length===state.failedKeys.length?"verified":"correction";else{const m=missions[state.mission];if(state.key<m.keys-1)state.key++;else state.stage="missionEnd"}save();render()}
  function speechMarkup(q){const extras=isDay6?`<strong>En kanelbulle, tack.</strong> —Un bollo de canela, por favor—.<br><strong>Var ligger hamnen?</strong> —¿Dónde está el puerto?—.`:isDay5?`<strong>En kanelbulle, tack.</strong> —Un bollo de canela, por favor—.<br><strong>Två glassar, tack.</strong> —Dos helados, por favor—.`:isDay4?`<strong>Var ligger Vitsand?</strong> —¿Dónde está Vitsand?—.<br><strong>Tack så mycket.</strong> —Muchas gracias—.`:isDay3?`<strong>Var ligger slottet?</strong> —¿Dónde está el castillo?—.<br><strong>Tack så mycket.</strong> —Muchas gracias—.`:`<strong>En kaffe, tack.</strong> —Un café, por favor—.<br><strong>Kan vi få notan, tack?</strong> —¿Nos trae la cuenta, por favor?—.`;return `<div class="speech-card"><button class="flashcard" id="flip-card" type="button"><span class="flash-front-speech"><small>TOCA PARA GIRAR</small><strong>${q.word}</strong></span><span class="flash-back-speech"><small>EN ESPAÑOL</small><strong>${q.meaning}</strong><em>${q.tip}</em></span></button><div class="speech-controls"><button id="listen-model" type="button">▶ Escuchar modelo</button><button id="record-voice" type="button">● Grabar mi voz</button><button id="play-record" type="button" ${recordUrl?"":"disabled"}>▶ Mi grabación</button></div><p class="fine">No hay nota automática. Si el micrófono no está disponible, puedes continuar.</p><details class="dossier"><summary>OTRAS FRASES ÚTILES</summary><p>${extras}</p></details></div>`}
  function bindSpeech(q){const flip=$("#flip-card");if(flip)flip.onclick=()=>flip.classList.toggle("flipped");const listen=$("#listen-model");if(listen)listen.onclick=()=>{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(q.speech);u.lang="sv-SE";u.rate=.82;speechSynthesis.speak(u)};const rec=$("#record-voice");if(rec)rec.onclick=async()=>{if(recorder?.state==="recording"){recorder.stop();rec.textContent="● Grabar mi voz";return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true}),chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>{if(recordUrl)URL.revokeObjectURL(recordUrl);recordUrl=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType}));stream.getTracks().forEach(t=>t.stop());const p=$("#play-record");if(p)p.disabled=false};recorder.start();rec.textContent="■ Detener grabación"}catch{rec.disabled=true;rec.textContent="Micrófono no disponible"}};const play=$("#play-record");if(play)play.onclick=()=>{if(recordUrl)new Audio(recordUrl).play()}}

  function missionEnd(){const m=missions[state.mission];if(!state.completedMissions.includes(state.mission)){state.completedMissions.push(state.mission);state.balance+=m.minimum;state.awarded[`mission-${state.mission}`]=m.minimum;save()}const next=state.mission+1;setChrome({progress:next/8*100});screen.className="screen result";screen.innerHTML=`<div class="mission-complete"><div class="seal">✓</div><p class="kicker">MISIÓN ${state.mission+1} DE 8 COMPLETADA</p><h1>${m.title}</h1><p>${m.done}</p><div class="reward-ledger"><div><span>Recompensa mínima</span><strong>+${m.minimum} kr</strong></div><div><span>Bonificación acumulada</span><strong>+${state.bonus} kr</strong></div><div><span>Fondo actualizado</span><strong>${state.balance} kr</strong></div><div><span>Progreso</span><strong>${next} de 8</strong></div></div><div class="fund-status">${fundMessage()}</div></div>`;if(next===8)setActions([{label:"Salir por ahora",kind:"secondary",run:()=>{state.stage="landing";save();render()}},{label:"Revisar la ruta completa",run:finishMissions}]);else setActions([{label:"Salir por ahora",kind:"secondary",run:()=>{state.mission=next;state.stage="landing";save();render()}},{label:`Ir a la misión ${next+1}`,run:()=>{state.mission=next;state.stage="missionCover";save();render()}}])}
  function finishMissions(){state.stage=state.failedKeys.length?"correctionIntro":"verified";save();render()}
  function correctionIntro(){const count=state.failedKeys.length,secured=state.balance>=300;setChrome({correction:true,progress:100});screen.className="screen dark";screen.innerHTML=`<p class="kicker">DÍA ${DAY} · CORRECCIÓN 0 DE ${count}</p><h1>${secured?"El canal ya está asegurado.":"La ruta conserva interferencias."}</h1><p>${count===1?"Solo reaparecerá una clave.":`Solo reaparecerán las ${count} claves que necesitaron otro intento.`} Las demás siguen selladas.</p><div class="correction-list">${state.failedKeys.map((id,i)=>`<div class="correction-item"><strong>${i+1}</strong><span>${findQuestion(id).q.title}</span></div>`).join("")}</div><p>${secured?"Puedes continuar o repararlas para añadir 25 kr a la reserva.":"Repararlas liberará las 25 kr restantes."}</p>`;const a=[];if(secured)a.push({label:"Continuar sin corregir",kind:"secondary",run:()=>{state.correctionSkipped=true;state.stage="verified";save();render()}});a.push({label:secured?"Reparar y ganar 25 kr":"Reparar las claves pendientes",run:()=>{state.stage="correction";save();render()}});setActions(a,true)}
  function correction(){const pending=state.failedKeys.filter(x=>!state.correctedKeys.includes(x));if(!pending.length){state.stage="verified";save();return render()}correctionQuestion(findQuestion(pending[0]).q)}
  function correctionQuestion(q){const scope=scopeFor(q,true);setChrome({correction:true,progress:100});screen.className="screen";screen.innerHTML=`<p class="key-count">CORRECCIÓN ${state.correctedKeys.length} DE ${state.failedKeys.length}</p><h2>${q.title}</h2><p>${q.prompt}</p>${visual(q.visual,q,scope)}${questionMarkup(q,scope)}<div id="feedback"></div>`;bindQuestion(q,scope,true)}
  function findQuestion(id){for(let mi=0;mi<missions.length;mi++){const qi=missions[mi].questions.findIndex(q=>q.id===id);if(qi>=0)return{q:missions[mi].questions[qi],mi,qi}}}
  function verified(){if(!state.correctionSkipped&&!state.awarded.verify){state.balance+=25;state.awarded.verify=25;save()}setChrome({progress:100});screen.className="screen dark center";const recovered=state.completedKeys.length-state.failedKeys.length+state.correctedKeys.length,status=state.correctionSkipped?`${state.failedKeys.length-state.correctedKeys.length} claves quedan sin corregir.`:state.failedKeys.length?"Todas las interferencias han sido retiradas.":"Ruta verificada sin interferencias.";screen.innerHTML=`<p class="kicker">OCHO MISIONES COMPLETADAS</p><h1>${isDay6?"La puerta occidental y el manifiesto moderno ya están unidos.":isDay5?"El plan de retirada y la línea infiltrada ya están separados.":isDay4?"El cuaderno ya separa las cuatro huellas.":isDay3?"La ruta Engelbrekt está completa.":"El nombre de Margareta está limpio."}</h1><div class="three-crowns">♛ ♛ ♛</div><p>${status}</p><div class="reward-ledger"><div><span>Sellado de la ruta</span><strong>${state.correctionSkipped?"omitido":"+25 kr"}</strong></div><div><span>Claves recuperadas</span><strong>${state.correctionSkipped?recovered:30} de 30</strong></div><div><span>Fondo recuperado</span><strong>${state.balance} kr</strong></div></div>`;setActions([{label:"Abrir la transmisión final",run:()=>{state.stage="fundFinal";save();render()}}],true)}
  function previousReserve(){try{const key=META.previousStore||"codigo-gripsholm-day01-v3",d=JSON.parse(localStorage.getItem(key)||"{}");return Math.max(0,(d.balance||0)-(d.spent||0))}catch{return 0}}
  function fundFinal(){const reserve=Math.max(0,state.balance-300),prev=previousReserve();setChrome({progress:100});screen.className="screen";screen.innerHTML=`<p class="kicker">DÍA ${DAY} · FONDO DE EMERGENCIA</p><h1>La ruta está a salvo.</h1><div class="reward-ledger"><div><span>Fondo recuperado hoy</span><strong>${state.balance} kr</strong></div><div><span>Canal y desplazamiento</span><strong>−300 kr</strong></div><div><span>Reserva añadida hoy</span><strong>${reserve} kr</strong></div><div><span>Reserva del Día ${META.previousDay||"01"}</span><strong>${prev} kr</strong></div><div><span>Reserva total</span><strong>${reserve+prev} kr</strong></div></div><p class="fine">Estas cantidades pertenecen a la ficción y no representan precios reales del viaje.</p>`;setActions([{label:"Asegurar la ruta y continuar",run:()=>{state.spent=300;state.endingPage=0;state.stage="ending";save();render()}}])}
  function ending(){setChrome({dark:true,progress:100});screen.className="screen dark";const reserve=state.balance-300+previousReserve(),pages=isDay3?[`<figure class="hero-photo"><img src="${imgBase}saga-canal-asegurado.png" alt="Saga cierra el Día 03"></figure><p class="kicker">SAGA · RUTA RECUPERADA</p><h2>Puente. Hierro. Castillo. Bosque.</h2><p>Mi padre no eligió a Engelbrekt porque quisiera llamarlo héroe. Lo eligió porque su historia une exactamente los lugares que necesitaba ocultar.</p><p class="lead">La acusación BANDIDO solo servía para impedirnos ver el mapa completo.</p>`,`<figure class="hero-photo"><img src="${imgBase}engelbrekt-statue-orebro.jpg" alt="Estatua posterior de Engelbrekt en Örebro"></figure><p class="kicker">ENGELBREKT · DRAMATIZACIÓN ESCRITA</p><h1>Un puente no pertenece para siempre a quien lo ocupa.</h1><p>El hierro reunió a quienes protestaban. El castillo convirtió la protesta en poder. Mi muerte no cerró la disputa y el rey también acabó perdiendo sus coronas.</p><p class="fine">La intervención es una recreación. La imagen muestra una estatua posterior.</p><p class="lead">Conserva la ruta, no la leyenda de un hombre perfecto.</p>`,`<p class="kicker">TERCERA CONSECUENCIA</p><h1>El archivo digital termina en Tiveden.</h1><div class="coordinate">TIVEDEN · CUADERNO DE PAPEL<br>CUSTODIA · ALVA NYSTRÖM<br>SEÑALES · GRIETA · ROCA · FUEGO · IGLESIA</div><p>El dispositivo desconocido intentó localizar un cuaderno que mis padres dejaron con una joven llamada Alva.</p><p class="lead">Mañana no podremos confiar en la cobertura. Si alguien nos sigue, el bosque también puede hacerle perder la ruta.</p><div class="reward-ledger"><div><span>Canal utilizado</span><strong>300 kr</strong></div><div><span>Reserva total</span><strong>${reserve} kr</strong></div></div>`]:[`<figure class="hero-photo"><img src="${imgBase}saga-canal-asegurado.png" alt="Saga cierra el Día 02"></figure><p class="kicker">SAGA · NOMBRE RECUPERADO</p><h2>Margareta no saboteó el Vasa.</h2><p>El barco era inestable. Lo sabían. Aun así zarpó con las portas abiertas y una ráfaga convirtió el problema en naufragio.</p><p class="lead">Quien manipuló el expediente quería un culpable sencillo. Nosotros hemos recuperado una cadena.</p>`,`<p class="kicker">MARGARETA NILSDOTTER · DRAMATIZACIÓN ESCRITA</p><h1>Mi nombre vuelve al contrato.</h1><p>No construí el barco sola. Nadie lo hizo.</p><p>Mantuve el astillero, sus cuentas y sus trabajadores cuando Henrik murió. El Vasa no llegó a la guerra, pero conservó durante siglos el trabajo de todos.</p><p class="lead">Ahora busca la ruta que alguien consultó después de Estocolmo.</p>`,`<p class="kicker">SEGUNDA CONSECUENCIA</p><h1>El mar se cierra. Se abre una carretera.</h1><div class="coordinate">ESTOCOLMO → ÖREBRO → TIVEDEN<br>NOMBRE ASOCIADO · ENGELBREKT<br>CONSULTA DESCONOCIDA · +6 HORAS</div><p>Ese fue el último itinerario auténtico de los padres de Saga. Seis horas después, otro dispositivo consultó la misma carretera.</p><p class="lead">Alguien va detrás de ellos.</p><div class="reward-ledger"><div><span>Canal utilizado</span><strong>300 kr</strong></div><div><span>Reserva total</span><strong>${reserve} kr</strong></div></div>`];screen.innerHTML=pages[state.endingPage];setActions([{label:state.endingPage===0?(isDay3?"Escuchar la última decisión":"Devolver el nombre"):state.endingPage===1?"Revelar la siguiente ruta":"Cerrar el canal",run:()=>{if(state.endingPage<2)state.endingPage++;else{state.stage="result";state.finished=true}save();render()}}],true)}
  function result(){setChrome({progress:100});screen.className="screen result";screen.innerHTML=isDay3?`<div class="mission-complete"><div class="seal">♛♛♛</div><p class="kicker">DÍA 03 COMPLETADO</p><h1>El puente y el rebelde</h1><p>8 de 8 misiones · ${state.correctionSkipped?"corrección aplazada":"30 de 30 claves"}<br>Ruta asegurada</p><div class="reward-ledger"><div><span>Reserva actual</span><strong>${state.balance-300+previousReserve()} kr</strong></div><div><span>Fragmentos</span><strong>${META.fragment||"4 de 11"}</strong></div></div><p><strong>Día 04:</strong> Tiveden · cuatro huellas · un cuaderno sin conexión.</p></div>`:`<div class="mission-complete"><div class="seal">♛♛♛</div><p class="kicker">DÍA 02 COMPLETADO</p><h1>Veinte minutos a flote</h1><p>8 de 8 misiones · ${state.correctionSkipped?"corrección aplazada":"30 de 30 claves"}<br>Ruta asegurada</p><div class="reward-ledger"><div><span>Reserva actual</span><strong>${state.balance-300+previousReserve()} kr</strong></div><div><span>Fragmentos</span><strong>3 de 11</strong></div></div><p><strong>Día 03:</strong> Örebro · Tiveden · Engelbrekt.</p></div>`;setActions([{label:"Ver las misiones",kind:"secondary",run:openMenu},{label:"Releer el cierre",run:()=>{state.endingPage=0;state.stage="ending";save();render()}}])}

  function d3RegionalSvg(final=false){return `<svg class="schematic-map regional d3-regional" viewBox="0 0 420 300" role="img" aria-label="Mapa esquemático de Estocolmo, Örebro y Tiveden"><rect width="420" height="300" class="schem-water"/><path class="schem-land" d="M0 0H420V300H0Z"/><path class="d3-lake" d="M276 55c38-18 83-2 97 21-18 20-66 27-101 12-13-10-10-24 4-33Z"/><path class="d3-lake" d="M209 111c32-13 71-3 82 16-15 17-54 23-82 9-11-7-10-17 0-25Z"/><path class="d3-lake big" d="M53 172c27-37 53-38 68 1 12 34 7 92-20 111-30-3-44-75-48-112Z"/><path class="d3-lake big" d="M165 174c22-31 44-26 48 9 5 39-4 89-27 105-26-12-34-75-21-114Z"/><path class="d3-river" d="M214 125Q187 132 156 128"/><path class="d3-road" d="M330 74Q252 85 156 128Q129 169 135 226"/><g class="forest-zone"><path d="M101 190L138 151L174 188L201 235L169 285H112L84 240Z"/></g><text class="schem-water-label" x="293" y="69">MÄLAREN</text><text class="schem-water-label" x="219" y="126">HJÄLMAREN</text><text class="schem-water-label" x="67" y="229">VÄNERN</text><text class="schem-water-label" x="171" y="232">VÄTTERN</text><circle class="schem-point" cx="330" cy="74" r="6"/><text class="schem-label" x="318" y="47">Estocolmo</text><circle class="schem-point" cx="156" cy="128" r="6"/><text class="schem-label" x="128" y="105">Örebro</text><circle class="schem-point" cx="135" cy="226" r="6"/><text class="schem-label" x="112" y="207">Tiveden</text><text class="schem-water-label" x="350" y="115">BÁLTICO</text><text class="route-distance" x="223" y="93">300–330 km</text>${final?`<text class="d3-code-label" x="250" y="163">PUENTE · HIERRO · CASTILLO</text><text class="d3-code-label strong" x="111" y="253">BOSQUE</text>`:""}</svg>`}
  function d3CitySvg(){return `<svg class="schematic-map regional d3-city" viewBox="0 0 420 300" role="img" aria-label="Mapa esquemático del centro de Örebro"><rect width="420" height="300" class="schem-land"/><path class="d3-river-wide" d="M0 142Q88 112 174 137T420 128"/><ellipse class="castle-island" cx="155" cy="133" rx="37" ry="27"/><rect class="castle-shape" x="134" y="117" width="42" height="30" rx="5"/><path class="schem-road" d="M154 160L154 221L220 244M176 134L229 135M238 134Q290 158 349 177"/><g class="d3-city-labels"><text x="114" y="96">CASTILLO</text><text x="190" y="119">STORBRON</text><text x="114" y="209">STORTORGET</text><text x="188" y="228">SAN NICOLÁS</text><text x="270" y="157">STADSPARKEN</text><text x="319" y="204">WADKÖPING</text></g><text class="schem-water-label" x="17" y="123">SVARTÅN</text><path class="schem-arrow" d="M350 107H402"/><text class="schem-water-label" x="310" y="91">HACIA HJÄLMAREN</text></svg>`}
  function d3RouteExplorer(){const pts=[[78,25],[67,26],[52,42],[37,43],[37,51],[42,65],[68,72],[32,80]];return `<section class="route-explorer"><div class="day2-city-map route-map d3-route-map" role="img" aria-label="Mapa esquemático desde Estocolmo hasta Tiveden">${d3RegionalSvg()}${pts.map((p,i)=>`<button type="button" class="route-pin ${state.exploredPlaces.includes(i)?"seen":""}" style="--x:${p[0]}%;--y:${p[1]}%" data-place="${i}" aria-label="Abrir ${esc(DATA.routePlaces[i][0])}">${state.exploredPlaces.includes(i)?"✓":i+1}</button>`).join("")}</div>${cityKey()}<p class="map-credit">Mapa esquemático de orientación · no sustituye un navegador</p><p class="placement-progress">Lugares abiertos: <strong>${state.exploredPlaces.length} de 8</strong></p><div id="place-detail"></div></section>`}
  function d3MapCard(title,svg,caption="Mapa esquemático · no sustituye un navegador"){if(title==="SUECIA · SCHLESWIG · HOLSTEIN · HANSA"){title="EL BÁLTICO · DINAMARCA · SCHLESWIG · HOLSTEIN";caption="Gotland y Öland quedan frente a la costa sueca; Kalmar está en el continente, frente a Öland. Al sur aparecen las costas alemana y polaca del Báltico."}return `<div class="puzzle-card map-card"><p class="kicker">${title}</p><div class="regional-schematic">${svg}</div><p class="map-caption">${caption}</p></div>`}
